        }
      },
      "example_create_new_file": {
        "description": "Создаём новый файл внутри соты (файла ещё не существует)",
        "patch": {
          "target_module": "honeycombs/seeds/core/resonance_idea",
          "content": "{\"identity\":{\"module_id\":\"SEEDS-010\",\"name\":\"Идея резонанса\",\"version\":\"v1.0.0\",\"created\":\"2026-03-05\"},\"meta\":{\"status\":\"active\",\"ttl_days\":30},\"content\":{\"idea\":\"Описание идеи\",\"source\":\"сессия 2026-03-05\"}}"
        }
      },
      "errors_to_avoid": [
        "НЕ использовать changes[] для honeycombs/ — это формат только для simbiosis/",
        "НЕ передавать частичный JSON — только полное содержимое файла",
        "НЕ забывать обновить registry.last_updated и версию в identity"
      ]
    },

    "2_simbiosis_patch": {
      "title": "Точечное обновление модуля simbiosis/",
      "rule": "changes[] работает ТОЛЬКО для simbiosis/. Для honeycombs/ используй format 1.",
      "fields": {
        "target_module": "путь БЕЗ .json",
        "changes": "массив операций [{op, path, value}]"
      },
      "operations": {
        "update": "изменить существующее поле",
        "add": "добавить новое поле или элемент в массив",
        "delete": "удалить поле (value не нужен)",
        "remove": "удалить элемент из массива по id",
        "replace": "полностью заменить блок",
        "merge": "слить объект с существующим"
      },
      "example": {
        "description": "Обновляем статус и версию модуля seeds",
        "patch": {
          "target_module": "simbiosis/seeds",
          "changes": [
            {"op": "update", "path": "meta.status", "value": "active"},
            {"op": "update", "path": "meta.version", "value": "v2.1.0"},
            {"op": "add", "path": "meta.tags", "value": "resonance"}
          ]
        }
      },
      "warning": "Ключи с дефисами (RM-001, GD-01) нельзя адресовать через точечный путь — только update на родительский блок целиком."
    },

    "3_text_file_patch": {
      "title": "Точечная замена в текстовом файле (.py, .html, .md, .txt)",
      "fields": {
        "file_path": "путь С расширением",
        "replacements": "массив [{old, new}] — применяются последовательно"
      },
      "rules": [
        "old должна встречаться в файле РОВНО 1 раз — иначе патч отклоняется",
        "Берй достаточно контекста в old: минимум полная строка, лучше 2-3 строки",
        "Порядок замен важен — каждая следующая применяется к уже изменённому файлу"
      ],
      "example": {
        "description": "Обновляем версию и добавляем флаг в main.py",
        "patch": {
          "file_path": "engineer-chat/main.py",
          "replacements": [
            {
              "old": "VERSION = \"v1.0.0\"",
              "new": "VERSION = \"v1.1.0\""
            },
            {
              "old": "FEATURE_FLAG = False",
              "new": "FEATURE_FLAG = True"
            }
          ]
        }
      }
    },

    "4_multi_patch": {
      "title": "Мульти-патч — несколько файлов за один раз",
      "fields": {
        "patches": "массив патчей — каждый по формату 1, 2 или 3"
      },
      "example": {
        "description": "Обновляем соту и текстовый файл одним патчем",
        "patch": {
          "patches": [
            {
              "target_module": "honeycombs/seeds/index",
              "content": "{\"identity\":{\"module_id\":\"HONEYCOMB-SEEDS-001\",\"version\":\"v1.2.0\"},\"registry\":{\"last_updated\":\"2026-03-05\"}}"
            },
            {
              "file_path": "engineer-chat/main.py",
              "replacements": [
                {"old": "SEEDS_VERSION = \"v1.1.0\"", "new": "SEEDS_VERSION = \"v1.2.0\""}
              ]
            }
          ]
        }
      }
    }
  },

  "checklist": [
    "✅ Прочитал актуальную версию файла через read_file",
    "✅ Для honeycombs/ использую content (полная замена), не changes",
    "✅ Для simbiosis/ использую changes[] с корректными op",
    "✅ Для .py/.html/.md использую replacements с уникальным old",
    "✅ Патч обёрнут в ```json ... ``` в ответе",
    "✅ В content — полный JSON, не частичный",
    "✅ Обновил version и last_updated в изменяемом файле"
  ]
}

